WITH flattened AS (SELECT id, host, log_ts, latency_ms, status_code, k, value FROM app_logs LATERAL VIEW EXPLODE(context) t AS k, value) SELECT id, log_ts, latency_ms, k, AVG(latency_ms) OVER w_grp host_avg_latency_ms, AVG(status_code) OVER (PARTITION BY YEAR(log_ts), host ORDER BY latency_ms, id, k ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) status_code_avg_3_prior, AVG(latency_ms) OVER (PARTITION BY k ORDER BY log_ts, id, k ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) latency_ms_avg_6, LAG(status_code, 1) OVER (PARTITION BY host ORDER BY status_code, id, k) prev_status_code FROM flattened WINDOW w_grp AS (PARTITION BY host);
